// Confere o pedido antes de gastar cota do Gemini. Pedido inválido recebe
// uma resposta 400 com a explicação, sem chamar a IA.
const corpo = $json.body || {};
const texto = typeof corpo.texto === 'string' ? corpo.texto.trim() : '';
const nota = Number(corpo.nota);
const erros = [];
if (!texto) erros.push('Envie o campo "texto" com a avaliação.');
if (texto.length > 2000) erros.push('O campo "texto" pode ter no máximo 2.000 caracteres.');
if (!Number.isInteger(nota) || nota < 1 || nota > 5) erros.push('Envie o campo "nota" com um número inteiro de 1 a 5.');

return {
  json: {
    valido: erros.length === 0,
    erro: erros.join(' '),
    texto,
    nota,
    // O rascunho gasta uma requisição a mais. Quem só quer o motivo envia false.
    incluir_rascunho: corpo.incluir_rascunho !== false,
  },
};

// Junta o motivo dado pela IA com a regra da avaliação crítica. A regra é fixa
// e fica aqui, em código: a IA classifica o motivo, mas não decide o que é crítico.
const pedido = $('Validar pedido').item.json;
const motivo = $json.output.classificacoes[0].motivo;

const NOMES = {
  nao_recebido: 'Não recebido',
  entrega_incompleta: 'Entrega incompleta',
  produto_errado: 'Produto errado',
  defeito_ou_qualidade: 'Defeito ou qualidade',
  atraso: 'Atraso ou problema na entrega',
  atendimento_e_pos_venda: 'Atendimento e pós-venda',
  elogio: 'Elogio',
  outro: 'Outro',
};

// Mesma regra de src/radar/automacao.py (eh_critica):
// nota 1 ou 2 e um motivo de reclamação identificado.
const nota = pedido.nota;
const critica = nota <= 2 && !['elogio', 'outro'].includes(motivo);

return {
  json: {
    motivo,
    motivo_nome: NOMES[motivo],
    nota,
    critica,
    precisa_de_rascunho: critica && pedido.incluir_rascunho,
    rascunho: null,
    aviso: 'Classificação feita por IA, que pode errar. O acerto medido está no repositório.',
    versao: { prompt: 'classificacao_v2', modelo: 'gemini-3.5-flash-lite' },
  },
};
